package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ScrapeUrlVO;

class ScrapeUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of scrape url of observed source")
  void test_scrape_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    ScrapeUrlValueHolder<Object> value = new ScrapeUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.scrapeUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getScrapeUrlValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getScrapeUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.scrapeUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getScrapeUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getScrapeUrl().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of scrape url of observed source")
  void test_scrape_url_value_holder_assign_value_object() {
    Object holder = new Object();
    ScrapeUrlValueHolder<Object> value = new ScrapeUrlValueHolder<>(holder);
    ScrapeUrlVO vo = ScrapeUrlVO.from("one");
    Assertions.assertFalse(value.getScrapeUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.scrapeUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getScrapeUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.scrapeUrl(Optional.empty()));
    Assertions.assertFalse(value.getScrapeUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.scrapeUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getScrapeUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of scrape url of observed source against the original")
  void test_scrape_url_value_holder_read() {
    Object holder = new Object();
    ScrapeUrlValueHolder<Object> value = new ScrapeUrlValueHolder<>(holder);
    ScrapeUrlVO vo = ScrapeUrlVO.from("one");
    ScrapeUrlVO other = ScrapeUrlVO.from("one");
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getScrapeUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readScrapeUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readScrapeUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.scrapeUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readScrapeUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readScrapeUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of scrape url of observed source")
  void test_scrape_url_value_holder_unset() {
    Object holder = new Object();
    ScrapeUrlValueHolder<Object> value = new ScrapeUrlValueHolder<>(holder);
    ScrapeUrlVO vo = ScrapeUrlVO.from("one");
    value.scrapeUrl(vo);
    Assertions.assertSame(holder, value.unsetScrapeUrlIfMatches("scrapeUrl_other"));
    Assertions.assertTrue(value.getScrapeUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetScrapeUrlIfMatches("scrapeUrl"));
    Assertions.assertFalse(value.getScrapeUrlValue().isPresent(),
        "The field name must clear the value");
    value.scrapeUrl(vo);
    Assertions.assertSame(holder, value.unsetScrapeUrl());
    Assertions.assertFalse(value.getScrapeUrlValue().isPresent(), "Unset must clear the value");
  }
}
